#include "../Source/Systems/PitchTimeClipRenderer.h"
#include <juce_cryptography/juce_cryptography.h>
#include <iostream>
#include <stdexcept>
using namespace hem::pitchtime;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(){try{
 auto root=juce::File::getCurrentWorkingDirectory().getChildFile("pitch-time-work").getChildFile("clip-fixtures-"+juce::Uuid().toString());check(root.createDirectory().wasOk(),"fixture directory");
 auto source=root.getChildFile("original.wav");juce::WavAudioFormat wav;auto stream=source.createOutputStream();std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.get(),48000,1,32,{},0));check(writer!=nullptr,"fixture writer");stream.release();std::vector<float> input(48007);for(size_t i=0;i<input.size();++i)input[i]=float(.2*std::sin(2*juce::MathConstants<double>::pi*440*i/48000));const float* ip=input.data();check(writer->writeFromFloatArrays(&ip,1,int(input.size())),"fixture write");writer.reset();auto originalHash=juce::SHA256(source).toHexString();
 ClipRenderRequest request;request.source=source;request.destination=PitchTimeClipRenderer::uniqueDestination(root);request.expectedSourceSha256=originalHash;request.sourceGeneration=7;request.frameCount=input.size();request.settings.channels=1;request.settings.durationRatio=1.5;request.settings.pitchSemitones=7;
 auto result=PitchTimeClipRenderer::render(request);if(result.status!=ClipRenderResult::Status::complete)std::cerr<<result.error<<"\n";check(result.status==ClipRenderResult::Status::complete,"real file render");check(result.metadata.sourceGeneration==7&&result.metadata.renderedFrames==72011,"metadata exact frames");check(juce::SHA256(source).toHexString()==originalHash,"original unchanged");check(juce::SHA256(request.destination).toHexString()==result.metadata.renderedSha256,"rendered hash");check(result.metadata.recipeJson.contains(backendIdentity),"recipe identity");
 std::vector<float> oracle;auto r=render(request.settings,input.size(),[&](auto off,float* const* dest,int n){std::copy_n(input.data()+off,n,dest[0]);return true;},[&](const float* const* src,int n){oracle.insert(oracle.end(),src[0],src[0]+n);return true;});check(r.status==Result::Status::complete,"oracle backend");std::unique_ptr<juce::AudioFormatReader> reader(wav.createReaderFor(request.destination.createInputStream().release(),true));check(reader&&reader->lengthInSamples==juce::int64(oracle.size())&&reader->usesFloatingPointData,"output actual decode");juce::AudioBuffer<float> decoded(1,int(oracle.size()));check(reader->read(&decoded,0,decoded.getNumSamples(),0,true,false),"decode output");for(size_t i=0;i<oracle.size();++i)check(decoded.getSample(0,int(i))==oracle[i],"actual backend sample equality");reader.reset();
 auto duplicate=PitchTimeClipRenderer::render(request);check(duplicate.status==ClipRenderResult::Status::failed,"existing destination rejected");check(juce::SHA256(request.destination).toHexString()==result.metadata.renderedSha256,"existing output unchanged");
 auto successFile=request.destination;request.destination=PitchTimeClipRenderer::uniqueDestination(root);request.expectedSourceSha256=juce::String::repeatedString("0",64);auto stale=PitchTimeClipRenderer::render(request);check(stale.status==ClipRenderResult::Status::failed&&!request.destination.exists(),"stale source rejected");request.expectedSourceSha256=originalHash;
 request.settings.correction.enabled=true;int cancellations=0;auto cancel=PitchTimeClipRenderer::render(request,[&]{return cancellations>=5;},[&](auto,const CorrectionFrame&){++cancellations;});check(cancel.status==ClipRenderResult::Status::cancelled&&!request.destination.exists(),"cancel no publication");
 request.settings.correction.enabled=true;bool occupied=false;auto racing=PitchTimeClipRenderer::render(request,{},[&](auto,const CorrectionFrame&){if(!occupied){occupied=true;check(request.destination.replaceWithText("other writer"),"race fixture");}});check(racing.status==ClipRenderResult::Status::failed&&request.destination.loadFileAsString()=="other writer","publication collision preserves other writer");request.destination.deleteFile();
  request.settings.correction.enabled=false;request.settings.durationRatio=1;request.settings.wetMix=0;request.settings.outputDb=-6;request.startFrame=17;request.frameCount=10007;auto selected=PitchTimeClipRenderer::render(request);check(selected.status==ClipRenderResult::Status::complete&&selected.metadata.renderedFrames==10007&&selected.metadata.sourceFrames==juce::int64(input.size()),"selected range metadata");reader.reset(wav.createReaderFor(request.destination.createInputStream().release(),true));juce::AudioBuffer<float> range(1,10007);check(reader&&reader->read(&range,0,10007,0,true,false),"selected range decode");for(int i=0;i<10007;++i)check(std::abs(range.getSample(0,i)-input[size_t(i+17)]*std::pow(10.,-.3))<1e-7,"file dry trim aligned once");reader.reset();request.destination.deleteFile();
 check(root.findChildFiles(juce::File::findDirectories,false,"hem-pitch-stage-*").isEmpty(),"staging cleaned after success/failure/cancel");check(juce::SHA256(source).toHexString()==originalHash,"source hash final");successFile.deleteFile();source.deleteFile();check(root.deleteFile(),"fixtures cleaned");std::cout<<"PASS file renderer: actual backend parity, exact frames, hashes, no overwrite, cancel, stale source, publication collision, staging cleanup\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}



